def compute_sequence(N):
    a = {}
    if N >= 1:
        a[1] = 1
    if N >= 2:
        a[2] = 1

    for n in range(3, N + 1):
        a_n_minus_1 = a[n-1]

        term1_index = a_n_minus_1
        term2_index = n - a_n_minus_1

        if term1_index not in a or term2_index not in a:
            # This should only happen if the sequence structure fails or N is too small.
            # For the purpose of calculation, we assume if we are calculating up to N, all necessary previous values are present.
            return f"Error: Index not found for n={n}. Need a_{term1_index} or a_{term2_index}."

        a_n = a[term1_index] + a[term2_index]
        a[n] = a_n

    return a

N_max = 32
try:
    sequence = compute_sequence(N_max)
    results = {k: sequence[k] for k in sorted(sequence.keys())}
    print("n: a_n")
    for n in sorted(results.keys()):
        print(f"{n}: {results[n]}")
except Exception as e:
    print(f"An error occurred: {e}")
